/** Where the CLI reads and writes: replaced in tests. */
export interface IO extends SetupEnv {
  out(text: string): void;
  err(text: string): void;
  /** Whether a person is at this terminal (who can finish a browser sign-in, and answer a question). */
  interactive?: boolean;
  /** Asks the person at the terminal a question and returns their answer (only when interactive). */
  ask?(question: string): Promise<string>;
}

export function processIO(): IO {
  return {
    out: (t) => process.stdout.write(t.endsWith("\n") ? t : `${t}\n`),
    err: (t) => process.stderr.write(t.endsWith("\n") ? t : `${t}\n`),
    interactive: Boolean(process.stdin.isTTY && process.stdout.isTTY),
    ask: async (question) => {
      const rl = createInterface({ input: process.stdin, output: process.stdout });
      try {
        return await rl.question(question);
      } catch {
        return ""; // Ctrl+D or Ctrl+C at the question: no
      } finally {
        rl.close();
      }
    },
    home: homedir(),
    env: process.env,
    run: runProgram,
    fetch: globalThis.fetch,
  };
}

/** A usage error: printed with a hint, exit code 2. */
class UsageError extends Error {}

/** A flag or endpoint name in kebab-case, the CLI's one spelling (snake_case is accepted too: --max_age, search_posts). */
function kebab(s: string): string {
  return s.replaceAll("_", "-");
}

/** The args with every flag's name in kebab-case (--max_age=60 → --max-age=60); values are kept as given. */
function kebabFlags(args: readonly string[]): string[] {
  const out: string[] = [];
  for (const [i, a] of args.entries()) {
    if (a === "--") {
      out.push(...args.slice(i));
      break;
    }
    const m = /^--([^=]+)(=.*)?$/s.exec(a);
    out.push(m ? `--${kebab(m[1] ?? "")}${m[2] ?? ""}` : a);
  }
  return out;
}

const CLIENT_OPTIONS = {
  "api-key": { type: "string" },
  "base-url": { type: "string" },
  help: { type: "boolean", short: "h" },
} as const;

/** Runs the CLI; returns the exit code. */
export async function main(argv: readonly string[], io: IO = processIO()): Promise<number> {
  const [first, ...rest] = argv;
  try {
    switch (first) {
      case undefined:
      case "help":
      case "--help":
      case "-h":
        io.out(usage());
        return 0;
      case "--version":
      case "-v":
      case "version":
        io.out(VERSION);
        return 0;
      case "init":
        return await init(rest, io);
      case "skill":
        return await skill(rest, io);
      case "endpoints":
        io.out(endpointList());
        return 0;
      case "tool":
      case "tools":
        return await tool(rest, io);
      default:
        return await endpoint(first, rest, io);
    }
  } catch (e) {
    return fail(e, io);
  }
}

function fail(e: unknown, io: IO): number {
  if (e instanceof UsageError) {
    io.err(`${e.message}\nRun \`socialtap help\` for usage.`);
    return 2;
  }
  if (e instanceof APIError) {
    const error = {
      code: e.code,
      status: e.status,
      message: e.message,
      retryable: e.retryable,
      remediation: e.remediation,
      param: e.param,
      details: e.details,
      doc_url: e.docUrl,
      request_id: e.requestId,
    };
    io.err(JSON.stringify({ error, credits_charged: e.creditsCharged }, null, 2));
    return 1;
  }
  io.err(e instanceof Error ? e.message : String(e));
  return 1;
}

function usage(): string {
  const platforms = [...new Set(COMMANDS.map((c) => c.platform))];
  return [
    `${PRODUCT_NAME} CLI ${VERSION}: public social media data as JSON.`,
    "",
    "Usage:",
    "  socialtap <platform> <endpoint> [<link, handle or query>] --<param> <value> ...",
    "                                                          call an endpoint (JSON on stdout)",
    "      --data                                                print only data (no meta or page)",
    "      --all [--max-pages N] [--max-credits N]                 walk a list: one item per line",
    "  socialtap endpoints                                     every endpoint, its params and price",
    "  socialtap tool [<name> [<json arguments>]]              the agent tools (as the MCP server serves them)",
    "  socialtap init [--agent <id>]...                        set up coding agents: skill + MCP server",
    "  socialtap skill                                         print the Agent Skill (SKILL.md)",
    "",
    `Options: --api-key <key> (default: $${API_KEY_ENV}), --base-url <url> (default: ${DEFAULT_BASE_URL}), --help.`,
    ...(KEYLESS_TOOLS.length ? [`The tools ${andList(KEYLESS_TOOLS)} need no API key.`] : []),
    `Platforms: ${platforms.join(", ")}. \`socialtap <platform>\` lists its endpoints, \`socialtap <platform> <endpoint> --help\` its params.`,
    "Flags and endpoint names take kebab-case or snake_case: --max-age or --max_age, search-posts or search_posts.",
    "A lone argument is the endpoint's link, handle or query: socialtap tiktok profile nasa is --handle nasa.",
  ].join("\n");
}

/** How a command's usage names its params: its identity param as the lone argument, the others as flags. */
function synopsis(c: Command, params: readonly CommandParam[]): string[] {
  return params.map((p) => (p.name === c.identity ? `<${p.name}>` : `--${kebab(p.name)} <${p.type}>`));
}

function endpointList(): string {
  return COMMANDS.map((c) => {
    const required = synopsis(
      c,
      c.params.filter((p) => p.required),
    );
    return `socialtap ${c.platform} ${kebab(c.name)} ${required.join(" ")}\n    ${c.summary} (${c.price}${c.kind === "list" ? " per page" : ""})`;
  }).join("\n");
}

function commandHelp(c: Command): string {
  const lines = [`socialtap ${c.platform} ${kebab(c.name)}: ${c.summary}`, `Endpoint ${c.endpoint}. Price: ${c.price}${c.kind === "list" ? " per page" : ""}.`];
  if (c.identity) lines.push(`Usage: socialtap ${c.platform} ${kebab(c.name)} <${c.identity}> [--<param> <value>...] (the lone argument is --${kebab(c.identity)})`);
  lines.push("", "Params:");
  for (const p of c.params) {
    lines.push(`  --${kebab(p.name)} <${p.enum ? p.enum.join("|") : p.type}>${p.required ? " (required)" : ""}`, `      ${p.description}`);
  }
  lines.push("", "Output:", "  --data               print only data (without meta and page)");
  if (c.kind === "list") {
    lines.push("", "List options:", "  --all                walk every page: one JSON item per line on stdout, a summary on stderr", "  --max-pages <n>      stop --all after n pages", "  --max-credits <n>    also stop --all before the walk spends more than n credits in total");
  }
  return lines.join("\n");
}

/**
 * The client for a command: with the key given or in the environment, or without one when `keyless` (KEYLESS_TOOLS).
 * It names itself the CLI (CLI_CLIENT_NAME), not the SDK it is built on.
 */
function client(values: { "api-key"?: string; "base-url"?: string }, io: IO, keyless = false): SocialTap {
  const apiKey = values["api-key"] ?? io.env[API_KEY_ENV];
  const options: ClientOptions = { apiKey: apiKey ?? "", fetch: io.fetch };
  if (values["base-url"]) options.baseURL = values["base-url"];
  if (!apiKey && !keyless) throw new Error(`missing API key: pass --api-key <key> or set ${API_KEY_ENV}${CLI_SIGNUP_URL ? `. Get one at ${CLI_SIGNUP_URL}` : ""}`);
  const c = apiKey ? new SocialTap(options) : keylessClient(() => new SocialTap(options));
  c._client = CLI_CLIENT_NAME;
  return c;
}

/** Names in prose: "a", "a and b", "a, b and c". */
function andList(names: readonly string[]): string {
  return names.length < 2 ? names.join("") : `${names.slice(0, -1).join(", ")} and ${names.at(-1)}`;
}

// ---- endpoints ----

async function endpoint(platform: string, rest: readonly string[], io: IO): Promise<number> {
  const ofPlatform = COMMANDS.filter((c) => c.platform === platform);
  if (ofPlatform.length === 0) throw new UsageError(`unknown command or platform: ${platform}`);
  const [name, ...args] = rest;
  const cmd = name === undefined ? undefined : ofPlatform.find((c) => kebab(c.name) === kebab(name));
  if (!cmd) {
    if (name !== undefined && !name.startsWith("-")) throw new UsageError(`unknown ${platform} endpoint: ${name} (known: ${ofPlatform.map((c) => kebab(c.name)).join(", ")})`);
    io.out(ofPlatform.map((c) => `socialtap ${c.platform} ${kebab(c.name)}: ${c.summary} (${c.price}${c.kind === "list" ? " per page" : ""})`).join("\n"));
    return 0;
  }
  const options: Record<string, { type: "string" | "boolean"; short?: string }> = { ...CLIENT_OPTIONS, data: { type: "boolean" } };
  if (cmd.kind === "list") Object.assign(options, { all: { type: "boolean" }, "max-pages": { type: "string" }, "max-credits": { type: "string" } });
  for (const p of cmd.params) options[kebab(p.name)] = { type: p.type === "boolean" ? "boolean" : "string" };
  checkFlags(cmd, args, options);
  const { values, positionals } = parse(args, options, true);
  if (values.help) {
    io.out(commandHelp(cmd));
    return 0;
  }
  takeArgument(cmd, positionals, values);
  const params = readParams(cmd, values);
  const c = client(values as { "api-key"?: string; "base-url"?: string }, io);
  if (cmd.kind === "get") {
    const r = await cmd.get(c, params);
    io.out(JSON.stringify(values.data ? r.data : { data: r.data, meta: r.meta }, null, 2));
    return 0;
  }
  if (!values.all) {
    const r = await cmd.list(c, params);
    io.out(JSON.stringify(values.data ? r.data : { data: r.data, page: r.page, meta: r.meta }, null, 2));
    return 0;
  }
  const pages = cmd.iterate(c, params, {
    ...optionalInt("max-pages", values["max-pages"], (n) => ({ maxPages: n })),
    ...optionalInt("max-credits", values["max-credits"], (n) => ({ maxCredits: n })),
  });
  for await (const item of pages) io.out(JSON.stringify(item));
  io.err(JSON.stringify({ pages: pages.pagesFetched, credits_charged: pages.creditsCharged, stop_reason: pages.stopReason, end_reason: pages.endReason }));
  return 0;
}

type Options = Record<string, { type: "string" | "boolean"; short?: string; multiple?: boolean }>;

function parse(args: readonly string[], options: Options, allowPositionals = false) {
  try {
    return parseArgs({ args: kebabFlags(args), options, strict: true, allowPositionals });
  } catch (e) {
    throw new UsageError(e instanceof Error ? e.message : String(e));
  }
}

/**
 * Refuses a flag the command doesn't take, saying which param it most likely means (suggestParam): --username on an
 * endpoint that takes handle is --handle, as the API itself would answer the query param.
 */
function checkFlags(cmd: Command, args: readonly string[], options: Options): void {
  for (const a of kebabFlags(args)) {
    if (a === "--") return;
    const m = /^--([^=]+)/.exec(a);
    if (!m || Object.hasOwn(options, m[1]!)) continue;
    const flag = m[1]!;
    const s = suggestParam(flag, cmd.params.map((p) => p.name));
    const p = cmd.params.find((x) => x.name === s);
    const known = cmd.params.map((x) => `--${kebab(x.name)}`).join(", ");
    throw new UsageError(
      `socialtap ${cmd.platform} ${kebab(cmd.name)} has no --${flag}${p ? `; did you mean --${kebab(p.name)}?` : "."} Its params: ${known}.`,
    );
  }
}

/** The lone argument is the command's identity param (a link, a handle, a query): `socialtap tiktok profile nasa`. */
function takeArgument(cmd: Command, positionals: readonly string[], values: Record<string, unknown>): void {
  if (positionals.length === 0) return;
  const usage = `socialtap ${cmd.platform} ${kebab(cmd.name)}`;
  if (!cmd.identity) throw new UsageError(`${usage} takes no argument: pass its params as flags (--<param> <value>)`);
  const flag = kebab(cmd.identity);
  if (positionals.length > 1) throw new UsageError(`${usage} takes one argument, its ${cmd.identity} (got ${positionals.length}): quote a value with spaces`);
  if (values[flag] !== undefined) throw new UsageError(`${usage}: the argument is --${flag}, which is given too: pass one`);
  values[flag] = positionals[0];
}

/** Short names tolerate one edit, longer ones two (the API's core.SuggestParam). */
const maxDistance = (s: string) => (s.length <= 4 ? 1 : 2);

/** Optimal-string-alignment distance (the API's). */
function editDistance(a: string, b: string): number {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array<number>(b.length).fill(0)]);
  for (let j = 0; j <= b.length; j++) d[0]![j] = j;
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      let v = Math.min(d[i - 1]![j]! + 1, d[i]![j - 1]! + 1, d[i - 1]![j - 1]! + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) v = Math.min(v, d[i - 2]![j - 2]! + 1);
      d[i]![j] = v;
    }
  return d[a.length]![b.length]!;
}

/**
 * The param an unknown name most likely means, as the API suggests one (core.SuggestParam): the same name in snake_case,
 * an alias (PARAM_ALIASES: username is handle), else the closest name within a small edit distance; "" when nothing is close.
 */
function suggestParam(name: string, accepted: readonly string[]): string {
  const n = name.trim().toLowerCase().replaceAll("-", "_");
  if (accepted.includes(n)) return n;
  if (Object.hasOwn(PARAM_ALIASES, n)) return PARAM_ALIASES[n]!.find((c) => accepted.includes(c)) ?? "";
  let best = "";
  let bestD = maxDistance(n) + 1;
  for (const a of accepted) {
    const d = editDistance(n, a);
    if (d < bestD) [best, bestD] = [a, d];
  }
  return best;
}

/** The command's params from the flags (read in kebab-case: kebabFlags), typed; required ones present. */
function readParams(cmd: Command, values: Record<string, unknown>): Record<string, unknown> {
  const params: Record<string, unknown> = {};
  for (const p of cmd.params) {
    const raw = values[kebab(p.name)];
    if (raw === undefined) {
      if (p.required) throw new UsageError(`socialtap ${cmd.platform} ${kebab(cmd.name)}: --${kebab(p.name)} is required (${p.description})`);
      continue;
    }
    params[p.name] = typed(p, raw);
  }
  return params;
}

function typed(p: CommandParam, raw: unknown): unknown {
  if (p.type === "boolean" || typeof raw !== "string") return raw;
  // An enum value is the API's to check: it also reads the shared vocabulary's words (sort=new is sort=newest).
  if (p.type === "string") return raw;
  const n = Number(raw);
  if (raw.trim() === "" || !Number.isFinite(n) || (p.type === "integer" && !Number.isInteger(n))) throw new UsageError(`--${kebab(p.name)} must be ${p.type === "integer" ? "an integer" : "a number"}`);
  return n;
}

function optionalInt<T>(flag: string, raw: unknown, wrap: (n: number) => T): T | Record<string, never> {
  if (raw === undefined) return {};
  const n = Number(raw);
  if (typeof raw !== "string" || !Number.isInteger(n) || n < 0) throw new UsageError(`--${flag} must be a non-negative integer`);
  return wrap(n);
}

// ---- tools ----

async function tool(rest: readonly string[], io: IO): Promise<number> {
  const { values, positionals } = (() => {
    try {
      return parseArgs({ args: kebabFlags(rest), options: CLIENT_OPTIONS, strict: true, allowPositionals: true });
    } catch (e) {
      throw new UsageError(e instanceof Error ? e.message : String(e));
    }
  })();
  const [name, json] = positionals;
  if (name === undefined) {
    io.out(TOOLS.map((t) => `${t.name}: ${t.title}${keylessTool(t.name) ? " (no API key needed)" : ""}`).join("\n") || "this API has no MCP server");
    return 0;
  }
  const def = findTool(name);
  if (!def) throw new UsageError(`unknown tool: ${name} (known: ${TOOLS.map((t) => t.name).join(", ")})`);
  // Without arguments, a tool that needs some prints its help instead of a call that can only fail.
  if (values.help || (json === undefined && required(def).length > 0)) {
    io.out(toolHelp(def));
    return 0;
  }
  let args: Record<string, unknown> = {};
  if (json !== undefined) {
    try {
      args = JSON.parse(json) as Record<string, unknown>;
    } catch {
      throw new UsageError(`tool arguments must be a JSON object, e.g. socialtap tool ${name} '{"url": "…"}'`);
    }
    if (args === null || typeof args !== "object" || Array.isArray(args)) throw new UsageError("tool arguments must be a JSON object");
  }
  const r = await callTool(client(values, io, keylessTool(name)), name, args);
  (r.isError ? io.err : io.out)(typeof r.output === "string" ? r.output : JSON.stringify(r.output, null, 2));
  return r.isError ? 1 : 0;
}

/** Whether the server answers the tool without an API key. */
function keylessTool(name: string): boolean {
  return (KEYLESS_TOOLS as readonly string[]).includes(name);
}

/** The names of a tool's required arguments. */
function required(def: ToolDefinition): string[] {
  const r = def.inputSchema.required;
  return Array.isArray(r) ? r.filter((x): x is string => typeof x === "string") : [];
}

/** A tool's help: what it does (its description, price and rules included) and its arguments, from its input schema. */
function toolHelp(def: ToolDefinition): string {
  const props = (def.inputSchema.properties ?? {}) as Record<string, { type?: unknown; enum?: unknown; description?: unknown }>;
  const req = required(def);
  const lines = [`socialtap tool ${def.name} '<json arguments>': ${def.title}`, "", def.description, ...(keylessTool(def.name) ? ["No API key needed."] : []), "", "Arguments:"];
  for (const [arg, s] of Object.entries(props)) {
    const type = Array.isArray(s.enum) ? s.enum.join("|") : typeof s.type === "string" ? s.type : "value";
    lines.push(`  ${arg} <${type}>${req.includes(arg) ? " (required)" : ""}`);
    if (typeof s.description === "string") lines.push(`      ${s.description}`);
  }
  const example = Object.fromEntries(req.map((r) => [r, "…"]));
  lines.push("", `Example: socialtap tool ${def.name} '${JSON.stringify(example)}'`);
  return lines.join("\n");
}

// ---- skill and init ----

async function skill(rest: readonly string[], io: IO): Promise<number> {
  const { values } = parse(rest, { "base-url": { type: "string" } });
  if (SKILLS_INDEX_PATH === null) throw new Error(`${PRODUCT_NAME} publishes no Agent Skill`);
  const skills = await fetchSkills(io, origin(values["base-url"] as string | undefined), SKILLS_INDEX_PATH);
  io.out(skills.map((s) => s.content).join("\n"));
  return 0;
}

/**
 * Refuses a key the API doesn't know (unauthorized) before an agent stores it, with where to get one. A key that may
 * not read the account (forbidden) still authenticates. When the API can't be reached the check is skipped and said:
 * the steps that follow need it anyway.
 */
async function verifyKey(key: string, from: string, baseURL: string | undefined, io: IO): Promise<void> {
  if (checkKey === null) return;
  const options: ClientOptions = { apiKey: key, fetch: io.fetch, maxRetries: 0 };
  if (baseURL) options.baseURL = baseURL;
  const c = new SocialTap(options);
  c._client = CLI_CLIENT_NAME;
  try {
    await checkKey(c);
  } catch (e) {
    if (e instanceof APIError && e.status === 401) {
      const next = CLI_SIGNUP_URL ? `Get a key at ${CLI_SIGNUP_URL}, or run init without one` : "Run init without a key";
      throw new Error(`The API key from ${from} was refused (${e.code}), so nothing was changed. ${next}: each agent then signs you in with your browser.`);
    }
    if (!(e instanceof APIError)) io.err(`Couldn't check the API key from ${from}: ${e instanceof Error ? e.message : String(e)}`);
  }
}

function origin(baseURL: string | undefined): string {
  return (baseURL ?? DEFAULT_BASE_URL).replace(/\/+$/, "");
}

async function init(rest: readonly string[], io: IO): Promise<number> {
  const ids = AGENTS.map((a) => a.id);
  const { values } = parse(rest, { ...CLIENT_OPTIONS, agent: { type: "string", multiple: true } } as Parameters<typeof parse>[1]);
  if (values.help) {
    io.out(
      [
        "socialtap init [--agent <id>]... [--api-key <key>] [--base-url <url>]",
        "",
        `Installs the ${PRODUCT_NAME} Agent Skill and registers the MCP server in each coding agent's user config.`,
        `Agents: ${AGENTS.map((a) => `${a.id} (${a.name})`).join(", ")}; default: every one installed (in a terminal, after you confirm).`,
        `The agent signs you in with your browser the first time a tool needs it. With --api-key, or $${API_KEY_ENV} set, it stores that key in plain text in the agent's config (readable only by you) and sends it instead; in a terminal, Claude Code still signs in with your browser unless you pass --api-key or its config already holds a key.`,
      ].join("\n"),
    );
    return 0;
  }
  const wanted = (values.agent as string[] | undefined) ?? [];
  for (const id of wanted) if (!ids.includes(id as AgentId)) throw new UsageError(`unknown agent ${id} (known: ${ids.join(", ")})`);
  const agents: Agent[] = wanted.length > 0 ? AGENTS.filter((a) => wanted.includes(a.id)) : AGENTS.filter((a) => a.detect(io));
  if (agents.length === 0) {
    throw new UsageError(`found no coding agent (${AGENTS.map((a) => a.name).join(", ")}); choose with --agent <${ids.join("|")}>`);
  }
  const given = values["api-key"] as string | undefined;
  const key = given ?? io.env[API_KEY_ENV];
  // A key no agent could use is refused before anything is written.
  if (key) await verifyKey(key, given ? "--api-key" : `$${API_KEY_ENV}`, values["base-url"] as string | undefined, io);
  if (wanted.length === 0) {
    // Every agent found, unasked: a person at the terminal confirms first; a script (no terminal) gets them all and is told.
    const names = agents.map((a) => `${a.name} (${a.id})`).join(", ");
    if (io.interactive && io.ask) {
      const answer = await io.ask(`Set up ${PRODUCT_NAME} in ${names}? This edits each one's user config. [y/N] `);
      if (!/^y(es)?$/i.test(answer.trim())) {
        io.out(`Nothing changed. Choose agents with --agent <${ids.join("|")}>.`);
        return 0;
      }
    } else {
      io.out(`Setting up every coding agent found: ${names} (choose with --agent <${ids.join("|")}>).`);
    }
  }
  const base = origin(values["base-url"] as string | undefined);
  let failed = 0;
  const note = (ok: boolean, line: string) => {
    if (!ok) failed++;
    io.out(`${ok ? "✓" : "✗"} ${line}`);
  };

  if (SKILLS_INDEX_PATH !== null) {
    try {
      const skills = await fetchSkills(io, base, SKILLS_INDEX_PATH);
      for (const dir of new Set(agents.map((a) => a.skillsDir(io)))) {
        const users = agents.filter((a) => a.skillsDir(io) === dir).map((a) => a.name);
        for (const file of await writeSkills(dir, skills)) note(true, `skill: ${file} (${users.join(", ")})`);
      }
    } catch (e) {
      note(false, `skill: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  if (MCP_PATH === null) {
    io.out(`(${PRODUCT_NAME} has no MCP server: skipped)`);
  } else {
    const entry = { name: MCP_SERVER_NAME, url: base + MCP_PATH };
    if (!key) io.out("No API key given: each agent signs you in with your browser the first time a tool needs it.");
    for (const a of agents) {
      // A key from the environment wasn't handed to `init` to keep. Claude Code signs in with the browser instead, so
      // the key stays out of its config and its command line, unless nobody is there to sign in or it already sends a key.
      const browser = !given && key && a.id === "claude" && io.interactive && !(await claudeHoldsKey(io, entry.name));
      const server: McpServer = key && !browser ? { ...entry, key } : entry;
      try {
        const path = await a.addMcp(io, server);
        note(true, `MCP server ${server.name} in ${a.name}: ${path}`);
        if (browser) io.out(`  didn't store $${API_KEY_ENV}: ${a.name} signs you in with your browser (--api-key stores a key instead)`);
        if (server.key) io.out(`  stored your API key in ${path}${given ? "" : `, from $${API_KEY_ENV}`} (plain text, readable only by you)`);
      } catch (e) {
        const why = (e as NodeJS.ErrnoException).code === "ENOENT" ? `its CLI is not on PATH` : e instanceof Error ? e.message : String(e);
        note(false, `MCP server in ${a.name}: ${why}${AGENTS_DOCS_URL ? `. Setup by hand: ${AGENTS_DOCS_URL}` : ""}`);
      }
    }
  }
  io.out(failed === 0 ? "Done. Restart your agents to load the changes." : `${failed} step(s) failed (above).`);
  return failed === 0 ? 0 : 1;
}
